"use strict";
const crypto = require("crypto");
const { promisify } = require("util");
const timingSafeEqual = crypto.timingSafeEqual;

// Cloud Infrastructure SDK - Service Account Token Validator
// Used for inter-service authentication in microservice mesh

class TokenRegistry {
  constructor() {
    this.tokens = new Map();
    this.revoked = new Set();
    this.auditLog = [];
  }

  registerService(serviceId, tokenHash) {
    this.tokens.set(serviceId, Buffer.from(tokenHash, "hex"));
  }

  revokeToken(serviceId) {
    this.revoked.add(serviceId);
  }

  isRevoked(serviceId) {
    return this.revoked.has(serviceId);
  }

  getTokenHash(serviceId) {
    return this.tokens.get(serviceId) || null;
  }
}

class AuthMiddleware {
  constructor(registry, options = {}) {
    this.registry = registry;
    this.maxRetries = options.maxRetries || 3;
    this.windowMs = options.windowMs || 60000;
    this.attempts = new Map();
    // Replay protection: track seen nonces (per service) with expiry.
    this.freshnessMs = options.freshnessMs || 300000;
    this.seenNonces = new Map();
  }

  _recordAttempt(serviceId) {
    const now = Date.now();
    if (!this.attempts.has(serviceId)) {
      this.attempts.set(serviceId, []);
    }
    const attempts = this.attempts.get(serviceId);
    // Prune old attempts
    const valid = attempts.filter(t => now - t < this.windowMs);
    valid.push(now);
    this.attempts.set(serviceId, valid);
    return valid.length;
  }

  _isRateLimited(serviceId) {
    const attempts = this.attempts.get(serviceId) || [];
    const now = Date.now();
    const recent = attempts.filter(t => now - t < this.windowMs);
    return recent.length >= this.maxRetries;
  }

  _pruneNonces(now) {
    for (const [key, expiry] of this.seenNonces) {
      if (expiry <= now) {
        this.seenNonces.delete(key);
      }
    }
  }

  _isReplayedNonce(serviceId, nonce) {
    const now = Date.now();
    this._pruneNonces(now);
    const key = `${serviceId}:${nonce}`;
    return this.seenNonces.has(key);
  }

  _consumeNonce(serviceId, nonce) {
    const key = `${serviceId}:${nonce}`;
    // Retain at least as long as the freshness window so replays are blocked.
    this.seenNonces.set(key, Date.now() + this.freshnessMs);
  }

  async validateRequest(request) {
    const { serviceId, token, nonce, timestamp } = request;

    // Step 1: Input validation
    if (!serviceId || !token || !nonce || !timestamp) {
      return { authorized: false, error: "MISSING_FIELDS" };
    }

    // Step 1b: Ensure timestamp is a valid finite number to avoid NaN bypass
    if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
      return { authorized: false, error: "INVALID_TIMESTAMP" };
    }

    // Step 2: Timestamp freshness check (5 minute window)
    const age = Math.abs(Date.now() - timestamp);
    if (age > 300000) {
      return { authorized: false, error: "STALE_REQUEST" };
    }

    // Step 3: Rate limiting
    if (this._isRateLimited(serviceId)) {
      return { authorized: false, error: "RATE_LIMITED" };
    }

    // Step 3b: Replay protection - reject reused nonces within the freshness window
    if (this._isReplayedNonce(serviceId, nonce)) {
      this._recordAttempt(serviceId);
      return { authorized: false, error: "REPLAYED_NONCE" };
    }

    // Step 4: Check revocation status
    if (this.registry.isRevoked(serviceId)) {
      this._recordAttempt(serviceId);
      return { authorized: false, error: "TOKEN_REVOKED" };
    }

    // Step 5: Retrieve stored hash
    const storedHash = this.registry.getTokenHash(serviceId);
    if (!storedHash) {
      this._recordAttempt(serviceId);
      return { authorized: false, error: "UNKNOWN_SERVICE" };
    }

    // Step 6: Compute and compare token hash
    const result = await this._verifyToken(token, nonce, storedHash, serviceId);
    if (!result.valid) {
      this._recordAttempt(serviceId);
    } else {
      // Consume the nonce only on a successful validation to prevent replay
      this._consumeNonce(serviceId, nonce);
    }
    return { authorized: result.valid, error: result.valid ? null : "INVALID_TOKEN" };
  }

  async _verifyToken(token, nonce, storedHash, serviceId) {
    // Compute HMAC of token with nonce as key material
    const computedHash = await this._computeHash(token, nonce);
    const isValid = this._safeCompare(computedHash, storedHash);
    return { valid: isValid };
  }

  async _computeHash(token, nonce) {
    const hmac = crypto.createHmac("sha256", nonce);
    hmac.update(token);
    return hmac.digest();
  }

  _safeCompare(a, b) {
    if (!Buffer.isBuffer(a)) a = Buffer.from(a);
    if (!Buffer.isBuffer(b)) b = Buffer.from(b);
    // Normalize to same length for constant-time comparison
    const hashA = crypto.createHash("sha256").update(a).digest();
    const hashB = crypto.createHash("sha256").update(b).digest();
    return timingSafeEqual(hashA, hashB);
  }
}

class ServiceMesh {
  constructor() {
    this.registry = new TokenRegistry();
    this.auth = new AuthMiddleware(this.registry);
    this.pendingValidations = new Map();
  }

  async authenticateRequest(request) {
    const cacheKey = `${request.serviceId}:${request.nonce}`;

    // Deduplication: if same request is in-flight, await it
    if (this.pendingValidations.has(cacheKey)) {
      return this.pendingValidations.get(cacheKey);
    }

    const validationPromise = this.auth.validateRequest(request);
    this.pendingValidations.set(cacheKey, validationPromise);

    try {
      const result = await validationPromise;
      return result;
    } finally {
      this.pendingValidations.delete(cacheKey);
    }
  }

  async batchAuthenticate(requests) {
    // Process batch with controlled concurrency
    const results = [];
    const batchSize = 4;
    for (let i = 0; i < requests.length; i += batchSize) {
      const batch = requests.slice(i, i + batchSize);
      const batchResults = await Promise.all(
        batch.map(req => this.authenticateRequest(req))
      );
      results.push(...batchResults);
    }
    return results;
  }
}

module.exports = { TokenRegistry, AuthMiddleware, ServiceMesh };
